MOD = 10**9 + 7

def count_valid_subsets(N, S):
    dp = [[-1] * 3 for _ in range(1 << N)]

    def dfs(mask, remainder):
        if mask == (1 << N) - 1:
            return 1 if remainder == 0 else 0
        if dp[mask][remainder] != -1:
            return dp[mask][remainder]

        count = dfs(mask | (1 << (N - 1)), (remainder * 10 + int(S[N - 1 - bin(mask).count('1')])) % 3)
        for i in range(N):
            if not (mask & (1 << i)):
                count = (count + dfs(mask | (1 << i), (remainder * 10 + int(S[i])) % 3)) % MOD

        dp[mask][remainder] = count
        return count

    return dfs(0, 0)

